using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.VTS.ReservacionesEstados{    [SwaggerSchema("Modelo de lectura de un ReservacionesEstado")]    [GraphQLDescription("Objeto que representa un ReservacionesEstado existente.")]    public class clReadReservacionesEstados    {        [SwaggerSchema("Identificador único del ReservacionesEstado")]        [GraphQLDescription("Identificador único del ReservacionesEstado")]        public int? ReservacionEstadoID { get; set; }        [SwaggerSchema("ReservacionEstado")]        [GraphQLDescription("ReservacionEstado")]        public string? ReservacionEstado { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un ReservacionesEstado")]    [GraphQLDescription("Input para crear un ReservacionesEstado.")]    public class clCreateReservacionesEstados    {        [GraphQLNonNullType] [SwaggerSchema("ReservacionEstado")]        [GraphQLDescription("ReservacionEstado")]        public string ReservacionEstado { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un ReservacionesEstado")]    [GraphQLDescription("Input para actualizar parcialmente un ReservacionesEstado.")]    public class clUpdateReservacionesEstados    {        [SwaggerSchema("Identificador único del ReservacionesEstado")]        [GraphQLDescription("Identificador único del ReservacionesEstado")]        public int? ReservacionEstadoID { get; set; }        [SwaggerSchema("ReservacionEstado")]        [GraphQLDescription("ReservacionEstado")]        public string? ReservacionEstado { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}